def brake():
    IN_A_1.on()
    IN_A_2.on()
    IN_B_1.on()
    IN_B_2.on()
    IN_C_1.on()
    IN_C_2.on()
    IN_D_1.on()
    IN_D_2.on()


def forward():
    IN_A_1.on()
    IN_A_2.off()
    IN_B_1.on()
    IN_B_2.off()
    IN_C_1.on()
    IN_C_2.off()
    IN_D_1.on()
    IN_D_2.off()
    
def reverse():
    IN_A_1.off()
    IN_A_2.on()
    IN_B_1.off()
    IN_B_2.on()
    IN_C_1.off()
    IN_C_2.on()
    IN_D_1.off()
    IN_D_2.on()

def free():
    IN_A_1.off()
    IN_A_2.off()
    IN_B_1.off()
    IN_B_2.off()
    IN_C_1.off()
    IN_C_2.off()
    IN_D_1.off()
    IN_D_2.off()


