def p(v, l=20, c="",a=[]):
    n = max(0, min(1, v / max(a)))  # 10bit ADCなので最大値は1023
    f = int(n * l)
    print(f"\r{RST}{GRN}{BLD}[{'|'*f}{' '*(l-f)}] {v}Hz{RST}", end=f"{c}")

def p2(v, l=20, c="",i=100,a=[]):
    n = max(0, min(1, v / i))  # 10bit ADCなので最大値は1023
    f = int(n * l)
    r = int(math.sin(0.4 * v + 0) * 127 + 128)
    g = int(math.sin(0.4 * v + 2 * math.pi / 3) * 127 + 128)
    b = int(math.sin(0.4 * v + 4 * math.pi / 3) * 127 + 128)
    print(f"\r{RST}{CYA}{BLD}\033[7m\033[38;2;{r};{g};{b}m[{'|'*f}{' '*(l-f)}] eta:{(sum(a)-sum(a[:v])):.0f}s{RST}", end=f"{c}")
